declarations.BASE_COLOR_ROLES:
/** The five model-chosen palette roles; every other role is derived from them. */
export const BASE_COLOR_ROLES = [
  "primary",
  "secondary",
  "accent",
  "text",
  "textSecondary",
] as const;

declarations.DERIVED_COLOR_ROLES:
/** Roles computed from the base roles by `deriveThemeRoles`. */
export const DERIVED_COLOR_ROLES = [
  "panel",
  "onPanel",
  "onAccent",
  "tile",
  "onTile",
] as const;

declarations.COLOR_ROLES:
/** Every linkable theme role. The single source the ColorRole type derives from. */
export const COLOR_ROLES = [
  ...BASE_COLOR_ROLES,
  ...DERIVED_COLOR_ROLES,
] as const;

declarations.ColorRole:
/**
 * A theme palette role that a color field can be linked to. When a field is
 * linked to a role, theme edits drive it by that link instead of by matching
 * its raw hex value — so two roles that share a color stay independent.
 */
export type ColorRole = (typeof COLOR_ROLES)[number];

declarations.ColorRefs:
/**
 * Optional links from a node's color fields (keyed by field name, e.g.
 * "backgroundColor", "textColor", "gradient0") to theme roles. Absent = the
 * field is a custom, unlinked color.
 */
export type ColorRefs = Partial<Record<string, ColorRole>>;

