declarations.Layout:
export interface Layout {
  /**
   * In format_layouts only: keep this phone size's screenshot choices while
   * deriving the design from the main layout. Without it the format layout is
   * an independent design. A format layout whose template differs from the
   * main layout's is ignored (the format follows main again).
   */
  phoneFormatImagesOnly?: boolean;
  template: TemplateType;
  platform: Platform;
  screens: Screen[]; // Screen-based structure (replaces all flat arrays)
  headers?: HeaderNode[]; // Headers are shared across screens (if needed)
  canvasWidth: number;
  canvasHeight: number;
  backgroundColor: string;
  backgroundGradient?: Gradient;
  colorRefs?: ColorRefs; // Optional links from layout background/gradient colors to theme roles
  panoramaBackground?: PanoramaBackground; // Panorama image that spans across all screens
  themeColors?: ThemeColors;
  /** Optional generated alternatives for layouts without a palette switcher. */
  themePaletteOptions?: ThemePaletteOptions;
  themePaletteMode?: ThemePaletteMode;
  orientation?: "portrait" | "landscape"; // Canvas orientation for phone/tablet layouts; undefined = portrait
  /** Skip the inter-screen gap in overflowing artwork; undefined keeps it enabled. */
  screenshotGap?: boolean;
  layerGroups?: LayerGroup[]; // Optional editor-only layer grouping metadata
}

