declarations.ASOCopy:
export interface ASOCopy extends ASOCopyTranslation {
  category: string; // Suggested App Store category
  subcategory: string; // Suggested subcategory (required)
  competitorAppIds?: Array<number | string>; // Store IDs of analyzed competitors
  competitorStoreProvider?: "app_store" | "google_play";
  competitorTargets?: Array<{
    appId: number | string;
    storeProvider: "app_store" | "google_play";
  }>;
  translations?: Record<string, ASOCopyTranslation>; // Localized ASO copy keyed by language code
  /** Per-language hash of the source copy each translation was produced from —
   * lets the translate route skip languages whose source hasn't changed. */
  translationSourceHashes?: Record<string, string>;
  /** Source fingerprints for each successfully translated field and language. */
  translationFieldSourceHashes?: Record<
    string,
    Partial<Record<ASOTranslationField, string>>
  >;
}

declarations.extractTranslationCopy:
/** Extract translation-relevant fields from an ASOCopy object. */
export function extractTranslationCopy(asoCopy: ASOCopy): ASOCopyTranslation {
  return {
    ...(asoCopy.whatsNew !== undefined ? { whatsNew: asoCopy.whatsNew } : {}),
    promotionalText: asoCopy.promotionalText,
    shortDescription: asoCopy.shortDescription,
    fullDescription: asoCopy.fullDescription,
    keywords: asoCopy.keywords,
    insights: asoCopy.insights,
  };
}

