declarations.PhoneFormat:
export interface PhoneFormat {
  id: PhoneFormatId;
  platform: "ios" | "android";
  label: string;
  /** Toolbar trigger text, kept to a word or two. */
  shortLabel: string;
  /** Devices the size covers, for the picker's secondary line. */
  devices: string;
  width: number;
  height: number;
  kind: PhoneFormatKind;
  /** Duo formats: the fold the device is shown at (1 open, 0 closed). */
  lidOpen?: number;
}

declarations.dims:
function dims(size: { width: number; height: number }) {
  return { width: size.width, height: size.height };
}

declarations.isPhoneFormatId:
export function isPhoneFormatId(value: unknown): value is PhoneFormatId {
  return (
    typeof value === "string" &&
    (PHONE_FORMAT_IDS as readonly string[]).includes(value)
  );
}

declarations.isCustomPhoneFormatId:
function isCustomPhoneFormatId(value: unknown): value is CustomPhoneFormatId {
  return value !== "main" && isPhoneFormatId(value);
}

declarations.getPhoneFormat:
export function getPhoneFormat(
  id: PhoneFormatId,
  platform: "ios" | "android",
): PhoneFormat | null {
  return (
    PHONE_FORMATS.find(
      (format) => format.id === id && format.platform === platform,
    ) ?? null
  );
}

declarations.phoneFormatForExportSize:
/** The format an export preset renders from, or null for "the main layout". */
export function phoneFormatForExportSize(
  platform: "ios" | "android",
  sizeId: string,
): CustomPhoneFormatId | null {
  if (platform === "ios") {
    if (sizeId === "duo-inner") return "ios-duo-inner";
    if (sizeId === "duo-outer") return "ios-duo-outer";
    if (sizeId === "6.5" || sizeId === "6.3" || sizeId === "6.1") {
      return `ios-${sizeId}`;
    }
    return null;
  }
  return sizeId === "play-high" ? "android-play-high" : null;
}

declarations.sanitizePhoneFormatLayouts:
/** Parse the stored map, dropping unknown keys and malformed entries. */
export function sanitizePhoneFormatLayouts(value: unknown): PhoneFormatLayouts {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const result: PhoneFormatLayouts = {};
  for (const [key, layout] of Object.entries(value)) {
    if (!isCustomPhoneFormatId(key)) continue;
    if (!layout || typeof layout !== "object") continue;
    if (!Array.isArray((layout as Layout).screens)) continue;
    result[key] = layout as Layout;
  }
  return result;
}

declarations.isPhoneFormatLayoutCurrent:
/** A custom layout made under another template no longer applies. */
function isPhoneFormatLayoutCurrent(
  custom: Layout | undefined,
  main: Layout,
): custom is Layout {
  return (
    Boolean(custom) &&
    (custom!.template || "default") === (main.template || "default")
  );
}

declarations.hasCustomPhoneFormatLayout:
/** Image choices alone do not make a format's design independent. */
export function hasCustomPhoneFormatLayout(
  custom: Layout | undefined,
  main: Layout,
): custom is Layout {
  return (
    isPhoneFormatLayoutCurrent(custom, main) && !custom.phoneFormatImagesOnly
  );
}

declarations.resolvePhoneFormatLayout:
/**
 * The layout a format shows: its own if it has a current one, otherwise the
 * main layout carried over to the format's canvas.
 */
export function resolvePhoneFormatLayout(
  main: Layout,
  formatLayouts: PhoneFormatLayouts | null | undefined,
  formatId: PhoneFormatId,
  platform: "ios" | "android",
): Layout {
  if (formatId === "main") return main;
  const custom = formatLayouts?.[formatId];
  if (isPhoneFormatLayoutCurrent(custom, main)) {
    return custom.phoneFormatImagesOnly
      ? applyPhoneFormatImages(
          derivePhoneFormatLayout(main, formatId, platform),
          custom,
        )
      : custom;
  }
  return derivePhoneFormatLayout(main, formatId, platform);
}

declarations.derivePhoneFormatLayout:
/** The main layout carried over to a format's canvas (no custom layout). */
export function derivePhoneFormatLayout(
  main: Layout,
  formatId: PhoneFormatId,
  platform: "ios" | "android",
): Layout {
  const format = getPhoneFormat(formatId, platform);
  if (!format || format.kind === "main") return main;
  const isLandscape = (main.orientation ?? "portrait") === "landscape";
  const width = isLandscape ? format.height : format.width;
  const height = isLandscape ? format.width : format.height;
  if (format.kind === "duo") {
    return deriveIphoneDuoLayout(main, {
      width,
      height,
      lidOpen: format.lidOpen ?? 1,
    });
  }
  return (
    syncLayoutDevicesToPlatform(
      scaleLayoutToTarget(main, width, height, { platform }),
      platform,
    ) ?? main
  );
}

declarations.phoneVisibleHeight:
/**
 * How tall a phone device is drawn, in canvas pixels. 2D frames and 3D models
 * have different natural bounds at the same `scale`, so measure each by its own.
 * Seeded rather than measured bounds: this runs on the export server too, and
 * a derived layout has to come out the same there as in the editor.
 */
function phoneVisibleHeight(
  screenshot: ScreenshotNode,
  canvasWidth: number,
): number | null {
  const modelId = screenshot.model3D?.modelId;
  if (screenshot.model3D) {
    const bounds = getSeededModel3DFrameBounds(
      modelId ?? "iphone-17-pro",
      canvasWidth,
    );
    return bounds.height * screenshot.scale;
  }
  const frame = get2DFrameBounds(screenshot);
  return frame ? frame.height * screenshot.scale : null;
}

declarations.phoneScreenInFrame:
/**
 * Where a 2D frame's phone actually is: its height and its centre's offset
 * from the frame image's centre, in frame pixels at scale 1. Null for 3D
 * models and frames without mapped screen corners.
 */
function phoneScreenInFrame(node: ScreenshotNode): {
  phoneHeight: number;
  screenWidth: number;
  offset: { x: number; y: number };
} | null {
  if (node.model3D) return null;
  const variant: PhoneVariant3D =
    node.variant3D === "none" ? "flat" : (node.variant3D ?? "flat");
  const frame = get2DFrameBounds(node);
  const corners = getPhoneSpec(node.phoneId || PhoneId.iPhone17ProMax)
    ?.variants3D?.[variant]?.screenCorners3D;
  if (!frame || !corners) return null;
  const { topLeft, topRight, bottomLeft, bottomRight } = corners;
  const edge = (a: { x: number; y: number }, b: { x: number; y: number }) =>
    Math.hypot(a.x - b.x, a.y - b.y);
  const screenHeight =
    (edge(topLeft, bottomLeft) + edge(topRight, bottomRight)) / 2;
  return {
    phoneHeight: screenHeight * PHONE_BODY_PER_SCREEN,
    screenWidth: (edge(topLeft, topRight) + edge(bottomLeft, bottomRight)) / 2,
    offset: {
      x:
        (topLeft.x + topRight.x + bottomLeft.x + bottomRight.x) / 4 -
        frame.width / 2,
      y:
        (topLeft.y + topRight.y + bottomLeft.y + bottomRight.y) / 4 -
        frame.height / 2,
    },
  };
}

declarations.duoNaturalHeight:
/**
 * The Duo's on-canvas height at layout scale 1. The silhouette is recorded
 * open and square to the camera (landscape); closed it is as tall and about
 * half as wide, and posed open-portrait its height is the open width.
 */
function duoNaturalHeight(canvasWidth: number, portraitOpen: boolean): number {
  const open = getSeededModel3DFrameBounds("iphone-duo", canvasWidth);
  return portraitOpen ? open.width : open.height;
}

declarations.DUO_OPEN_MAX_HEIGHT_SHARE:
// In seeded-silhouette units, which run ~10% under what the renderer draws
// (the phone seeds were hand-tuned small), so 0.6 lands near two thirds.
const DUO_OPEN_MAX_HEIGHT_SHARE = 0.8;

declarations.duoScreenSize:
/**
 * The Duo's display on the canvas at a layout scale, in view orientation:
 * unfolded it is posed portrait (the landscape panel turned a quarter),
 * folded it shows the portrait cover display.
 */
function duoScreenSize(
  canvasWidth: number,
  open: boolean,
  scale: number,
): { width: number; height: number } {
  const bounds = getSeededModel3DFrameBounds("iphone-duo", canvasWidth);
  if (open) {
    return {
      width: bounds.height * DUO_INNER_SCREEN.short * scale,
      height: bounds.width * DUO_INNER_SCREEN.long * scale,
    };
  }
  return {
    width: bounds.height * DUO_CLOSED_ASPECT * DUO_COVER_SCREEN.width * scale,
    height: bounds.height * DUO_COVER_SCREEN.height * scale,
  };
}

declarations.phoneScreenSize:
/** A phone's display on the canvas, in layout pixels. */
function phoneScreenSize(
  node: ScreenshotNode,
  canvasWidth: number,
): { width: number; height: number } | null {
  if (node.model3D) {
    const modelId = node.model3D.modelId ?? "iphone-17-pro";
    const bounds = getSeededModel3DFrameBounds(modelId, canvasWidth);
    const insets = DEVICE_MODEL_SPECS[modelId].screenInsets;
    return {
      width: bounds.width * insets.width * node.scale,
      height: bounds.height * insets.height * node.scale,
    };
  }
  const screen = phoneScreenInFrame(node);
  if (screen) {
    return {
      width: screen.screenWidth * node.scale,
      height: (screen.phoneHeight / PHONE_BODY_PER_SCREEN) * node.scale,
    };
  }
  const frame = get2DFrameBounds(node);
  return frame
    ? {
        width: frame.width * 0.9 * node.scale,
        height: frame.height * 0.9 * node.scale,
      }
    : null;
}

declarations.DuoScreenMapping:
/**
 * How a phone's display maps onto the Duo that replaces it: where each sat,
 * and how much the display grew on each axis (the Duo's displays are wider
 * for their height, and the screenshot stretches to them).
 */
interface DuoScreenMapping {
  phoneCenter: { x: number; y: number };
  duoCenter: { x: number; y: number };
  scaleX: number;
  scaleY: number;
  tilt: number;
}

declarations.remapMagnifier:
/**
 * Magnifiers enlarge a region of a phone's screenshot. Their size is in
 * screenshot pixels and their place is relative to the phone, so carrying
 * them over like free elements leaves them phone-sized and off the content.
 * Re-anchor each to its Duo: same offset from the display centre, scaled by
 * how the display grew, through the device's tilt.
 */
function remapMagnifier(
  magnifier: MagnifierNode,
  mapping: DuoScreenMapping,
): MagnifierNode {
  const { tilt } = mapping;
  const dx = magnifier.position.x - mapping.phoneCenter.x;
  const dy = magnifier.position.y - mapping.phoneCenter.y;
  // Into the device's frame, stretch, and back out.
  const lx = dx * Math.cos(-tilt) - dy * Math.sin(-tilt);
  const ly = dx * Math.sin(-tilt) + dy * Math.cos(-tilt);
  const sx = lx * mapping.scaleX;
  const sy = ly * mapping.scaleY;
  const zoom = mapping.scaleY;
  return {
    ...magnifier,
    position: {
      x: mapping.duoCenter.x + sx * Math.cos(tilt) - sy * Math.sin(tilt),
      y: mapping.duoCenter.y + sx * Math.sin(tilt) + sy * Math.cos(tilt),
    },
    scale: magnifier.scale * zoom,
    borderWidth: magnifier.borderWidth * zoom,
    cornerRadius: magnifier.cornerRadius * zoom,
  };
}

declarations.duoFinishFor:
function duoFinishFor(
  model: Model3DConfig | undefined,
): Model3DConfig["finish"] {
  const remembered = model?.devicesByPlatform?.ios;
  if (
    remembered?.modelId === "iphone-duo" &&
    DUO_FINISHES.includes(remembered.finish)
  ) {
    return remembered.finish;
  }
  if (model && DUO_FINISHES.includes(model.finish)) return model.finish;
  // Match the house look: light iPhone finishes get the light Duo.
  const light = model?.finish === "silver" || model?.finish === "glacier";
  return light
    ? "duo-star-white"
    : getDefaultFinishForDeviceModel("iphone-duo");
}

declarations.placeScreen:
/** Moves every positioned node of a uniformly scaled screen with `place`. */
function placeScreen(
  original: Layout["screens"][number],
  scaled: Layout["screens"][number],
  place: (position: { x: number; y: number }) => { x: number; y: number },
): Layout["screens"][number] {
  const move = <T extends Positioned>(nodes: T[] | undefined, from?: T[]) =>
    nodes?.map((node, index) => ({
      ...node,
      position: place((from ?? nodes)[index]!.position),
    }));
  return {
    ...scaled,
    screenshots: move(scaled.screenshots, original.screenshots)!,
    texts: move(scaled.texts, original.texts)!,
    pills: move(scaled.pills, original.pills),
    badges: move(scaled.badges, original.badges),
    ratings: move(scaled.ratings, original.ratings),
    illustrations: move(scaled.illustrations, original.illustrations),
    magnifiers: move(scaled.magnifiers, original.magnifiers),
    logo:
      scaled.logo && original.logo
        ? { ...scaled.logo, position: place(original.logo.position) }
        : scaled.logo,
  };
}

declarations.deriveIphoneDuoLayout:
/**
 * The main layout re-staged for the iPhone Duo: the canvas takes the Duo's App
 * Store size, everything else is carried over the way the iPad layout is, and
 * every phone becomes a 3D Duo — unfolded and turned portrait for the inner
 * display, folded for the outer one — kept at the share of the canvas height
 * the phone had.
 */
function deriveIphoneDuoLayout(
  main: Layout,
  target: { width: number; height: number; lidOpen: number },
): Layout {
  const baseWidth = main.canvasWidth || 1290;
  const baseHeight = main.canvasHeight || 2796;
  const scaleX = target.width / baseWidth;
  const scaleY = target.height / baseHeight;
  // The Duo canvases have another aspect than a phone's (the inner one is
  // 1.56x as wide, the outer one 73% as tall). Stretching positions per axis
  // while sizes follow one factor pulled compositions apart: a grid of
  // widgets spread out with gaps between the cards. So each screen's
  // composition is scaled as a whole by the tighter axis and centred on the
  // new canvas, keeping every element where it was relative to the others.
  const fontScale = Math.min(scaleX, scaleY);
  const marginX = target.width - baseWidth * fontScale;
  const marginY = (target.height - baseHeight * fontScale) / 2;
  // Positions are local to the owning screen but may lie on a neighbour
  // (overflow); centre each on the screen it is drawn over.
  const placeX = (x: number) =>
    x * fontScale + (Math.floor(x / baseWidth) + 0.5) * marginX;
  const place = (position: { x: number; y: number }) => ({
    x: placeX(position.x),
    y: position.y * fontScale + marginY,
  });
  const open = target.lidOpen >= 0.5;

  const toDuo = (
    original: ScreenshotNode,
    scaled: ScreenshotNode,
    mappings: Map<string, DuoScreenMapping>,
  ): ScreenshotNode => {
    // Tablets, laptops and watches stay what they are, sized like the type.
    if (original.tabletId || original.desktopId || original.watchId) {
      return { ...scaled, scale: original.scale * fontScale };
    }
    // An authored Duo is already a composition, including deliberately mixed
    // open/closed devices. Carry it over without re-posing or re-fitting it.
    if (original.model3D?.modelId === "iphone-duo") {
      return {
        ...scaled,
        variant3D: original.variant3D,
        model3D: { ...original.model3D },
        scale: original.scale * (fontScale / scaleX),
      };
    }
    // A frame image can hold more than the phone (a hand, perspective), so
    // size and place the Duo by the phone's own screen where it is known.
    const screen = phoneScreenInFrame(original);
    const phoneHeight = screen
      ? screen.phoneHeight * original.scale
      : phoneVisibleHeight(original, baseWidth);
    // The node's position is the frame image's centre; the phone may sit off
    // it (high-left in the handheld art). Move to the phone, through the
    // frame's tilt, then onto the target canvas like every other position.
    const tilt = ((original.tiltAngle ?? 0) * Math.PI) / 180;
    const position = screen
      ? place({
          x:
            original.position.x +
            (screen.offset.x * Math.cos(tilt) -
              screen.offset.y * Math.sin(tilt)) *
              original.scale,
          y:
            original.position.y +
            (screen.offset.x * Math.sin(tilt) +
              screen.offset.y * Math.cos(tilt)) *
              original.scale,
        })
      : scaled.position;
    const naturalHeight = duoNaturalHeight(target.width, open);
    // The phone's share of the canvas height, carried over. Folded, the Duo
    // is far wider for its height than a phone, so it stops short of the
    // canvas edges sooner.
    const share = phoneHeight
      ? Math.min(
          open ? DUO_OPEN_MAX_HEIGHT_SHARE : DUO_CLOSED_MAX_HEIGHT_SHARE,
          phoneHeight / baseHeight,
        )
      : 0;
    const scale =
      share > 0 && naturalHeight > 0
        ? (share * target.height) / naturalHeight
        : scaled.scale;
    const duoScale = Math.min(5, Math.max(0.1, scale));
    const phoneScreen = phoneScreenSize(original, baseWidth);
    if (phoneScreen && phoneScreen.width > 0 && phoneScreen.height > 0) {
      const duoScreen = duoScreenSize(target.width, open, duoScale);
      const offset = screen?.offset ?? { x: 0, y: 0 };
      mappings.set(original.id, {
        phoneCenter: {
          x:
            original.position.x +
            (offset.x * Math.cos(tilt) - offset.y * Math.sin(tilt)) *
              original.scale,
          y:
            original.position.y +
            (offset.x * Math.sin(tilt) + offset.y * Math.cos(tilt)) *
              original.scale,
        },
        duoCenter: position,
        scaleX: duoScreen.width / phoneScreen.width,
        scaleY: duoScreen.height / phoneScreen.height,
        tilt,
      });
    }
    const model = original.model3D;
    const finish = duoFinishFor(model);
    return {
      ...scaled,
      position,
      // Clamped to the editor's 3D scale range (500%).
      scale: duoScale,
      // Variant perspectives are 2D-frame art. The tilt is kept: it is the
      // node's roll on the canvas for 3D models too.
      variant3D: undefined,
      model3D: {
        ...(model ?? {}),
        modelId: "iphone-duo",
        finish,
        rotationX: model?.rotationX ?? 0,
        rotationY: model?.rotationY ?? 0,
        // Ordinary phone frames carry their authored canvas tilt. Preserve
        // that conversion; already-authored Duo nodes bypass it above.
        rotationZ: (model?.rotationZ ?? 0) - (open ? Math.PI / 2 : 0),
        lidOpen: target.lidOpen,
        devicesByPlatform: {
          ...model?.devicesByPlatform,
          ios: { modelId: "iphone-duo", finish },
        },
      },
    };
  };

  return {
    ...main,
    platform: "ios",
    canvasWidth: target.width,
    canvasHeight: target.height,
    screens: main.screens.map((screen) => {
      const uniform = scaleLayoutScreen(screen, {
        scaleX: fontScale,
        scaleY: fontScale,
        fontScale,
        screenshotScale: 1,
        illustrationScale: 1,
        screenshotDeviceUpdates: {},
        platform: "ios",
      });
      const scaled = placeScreen(screen, uniform, place);
      const mappings = new Map<string, DuoScreenMapping>();
      const screenshots = scaled.screenshots.map((node, index) =>
        toDuo(screen.screenshots[index]!, node, mappings),
      );
      // scaleLayoutScreen's illustrationScale is an absolute override (the
      // iPad templates pin authored sizes with it), so passing it through set
      // every illustration to 1: a 0.5 widget doubled, a 2.27 photo shrank.
      // Scale each by the type's factor instead; its width, height and
      // reference width stay, since the drawn size is those times the scale.
      const illustrations = screen.illustrations?.map(
        (illustration, index) => ({
          ...scaled.illustrations![index]!,
          scale: (illustration.scale || 1) * fontScale,
          width: illustration.width,
          height: illustration.height,
        }),
      );
      // A magnifier without a (still present) link reads the screen's first
      // screenshot, as the renderer does.
      const fallback = screen.screenshots[0]?.id;
      return {
        ...scaled,
        screenshots,
        ...(illustrations && { illustrations }),
        ...(screen.magnifiers && {
          magnifiers: screen.magnifiers.map((magnifier, index) => {
            const mapping =
              mappings.get(magnifier.screenshotId) ??
              (fallback ? mappings.get(fallback) : undefined);
            return mapping
              ? remapMagnifier(magnifier, mapping)
              : scaled.magnifiers![index]!;
          }),
        }),
      };
    }),
  };
}

declarations.nearestQuarterTurn:
/** Nearest quarter-turn, with half turns rounded away from zero on both sides. */
export function nearestQuarterTurn(degrees: number): number {
  return Math.sign(degrees) * Math.round(Math.abs(degrees) / 90);
}

declarations.getScreenshotTiltQuarterTurns:
/** Old saved layouts retain their authored mapping until an orientation edit. */
export function getScreenshotTiltQuarterTurns(
  screenshot: OrientedScreenshot,
): number {
  if (screenshot.contentOrientation?.version !== 1) return 0;
  return nearestQuarterTurn(
    (screenshot.tiltAngle ?? 0) - screenshot.contentOrientation.initialTilt,
  );
}

declarations.getScreenshotEffectiveFitMode:
/** Contain is a reversible orientation default, never a rewrite of authored fit. */
export function getScreenshotEffectiveFitMode(
  screenshot: OrientedScreenshot & Pick<ScreenshotNode, "fitMode">,
): ScreenshotFitMode {
  const authored = screenshot.fitMode ?? "stretch";
  return authored === "stretch" &&
    screenshot.contentOrientation?.fit === "auto" &&
    Math.abs(getScreenshotTiltQuarterTurns(screenshot) % 2) === 1
    ? "contain"
    : authored;
}

declarations.getScreenshotFitUpdates:
/** An explicit fit selection takes precedence over future orientation defaults. */
export function getScreenshotFitUpdates(
  screenshot: OrientedScreenshot,
  fitMode: ScreenshotFitMode,
): Partial<ScreenshotNode> {
  return {
    fitMode,
    contentOrientation: {
      ...(screenshot.contentOrientation ?? {
        version: 1,
        initialTilt: screenshot.tiltAngle ?? 0,
      }),
      fit: "manual",
    },
  };
}

declarations.DEFAULT_FONT_FAMILY:
/**
 * Default font family when none is specified
 */
const DEFAULT_FONT_FAMILY = "Poppins";

declarations.collectFontsFromRichContent:
/**
 * Collect all font families from a TiptapJSON rich content object
 */
/**
 * Every font a document references — the document default plus any `textStyle`
 * mark. Exported so "is this selection mixed?" is answered the same way here,
 * in the global font control and in the multi-selection panel.
 */
export function collectFontsFromRichContent(
  richContent: TiptapJSON,
  fonts: Set<string>,
): void {
  // Check document-level default font
  if (richContent.attrs?.defaultFontFamily) {
    fonts.add(richContent.attrs.defaultFontFamily);
  }

  // Traverse content to find fonts in textStyle marks
  for (const paragraph of richContent.content || []) {
    if (!paragraph.content) continue;

    for (const node of paragraph.content) {
      if (node.type !== "text" || !node.marks) continue;

      for (const mark of node.marks) {
        if (mark.type === "textStyle" && mark.attrs?.fontFamily) {
          fonts.add(mark.attrs.fontFamily);
        }
      }
    }
  }
}

declarations.detectGlobalFontFamily:
/**
 * Detect the global font family across all text elements in a layout.
 * Returns the font name if all elements use the same font, or null if mixed.
 */
export function detectGlobalFontFamily(layout: Layout): string | null {
  const fonts = new Set<string>();

  for (const screen of layout.screens) {
    // Check texts
    for (const text of screen.texts || []) {
      collectFontsFromRichContent(text.richContent, fonts);
    }

    // Check pills
    for (const pill of screen.pills || []) {
      if (pill.richContent) {
        collectFontsFromRichContent(pill.richContent, fonts);
      }
    }
  }

  // If no fonts found, return default
  if (fonts.size === 0) {
    return DEFAULT_FONT_FAMILY;
  }

  // If exactly one font, return it
  if (fonts.size === 1) {
    return [...fonts][0];
  }

  // Mixed fonts
  return null;
}

declarations.updateRichContentFontFamily:
/**
 * Update the font family for a single rich content object
 */
export function updateRichContentFontFamily(
  richContent: TiptapJSON,
  fontFamily: string,
): TiptapJSON {
  // Update document-level default
  const updatedAttrs = {
    ...richContent.attrs,
    defaultFontFamily: fontFamily,
  };

  // Update all textStyle marks in content
  const updatedContent = richContent.content.map((paragraph) => {
    if (!paragraph.content) return paragraph;

    const updatedParagraphContent = paragraph.content.map((node) => {
      if (node.type !== "text") return node;

      // If no marks, add textStyle with fontFamily
      if (!node.marks || node.marks.length === 0) {
        return {
          ...node,
          marks: [{ type: "textStyle" as const, attrs: { fontFamily } }],
        };
      }

      // Update existing marks
      let hasTextStyle = false;
      const updatedMarks = node.marks.map((mark) => {
        if (mark.type === "textStyle") {
          hasTextStyle = true;
          return {
            ...mark,
            attrs: {
              ...mark.attrs,
              fontFamily,
            },
          };
        }
        return mark;
      });

      // Add textStyle if not present
      if (!hasTextStyle) {
        updatedMarks.push({
          type: "textStyle" as const,
          attrs: { fontFamily },
        });
      }

      return { ...node, marks: updatedMarks };
    });

    return { ...paragraph, content: updatedParagraphContent };
  });

  return {
    ...richContent,
    attrs: updatedAttrs,
    content: updatedContent,
  };
}

declarations.updateAllElementsFontFamily:
/**
 * Update font family for all text elements in a layout
 */
export function updateAllElementsFontFamily(
  layout: Layout,
  fontFamily: string,
): Layout {
  const updatedScreens = layout.screens.map((screen) => {
    const updatedScreen = { ...screen };

    // Update texts
    updatedScreen.texts = screen.texts.map((text) => ({
      ...text,
      richContent: updateRichContentFontFamily(text.richContent, fontFamily),
    }));

    // Update pills
    if (screen.pills) {
      updatedScreen.pills = screen.pills.map((pill) => ({
        ...pill,
        richContent: updateRichContentFontFamily(pill.richContent, fontFamily),
      }));
    }

    return updatedScreen;
  });

  return {
    ...layout,
    screens: updatedScreens,
  };
}

declarations.CJK_LANGUAGE_MAP:
/** Languages that require CJK glyphs. */
const CJK_LANGUAGE_MAP: Record<string, ScriptSupport> = {
  ja: "cjk-ja",
  ko: "cjk-ko",
  zh: "cjk-sc", // default Chinese → Simplified
  "zh-cn": "cjk-sc",
  "zh-tw": "cjk-tc",
  "zh-hk": "cjk-tc",
};

declarations.FONT_FALLBACKS:
/** Visually similar fallback font for each font that lacks a script. */
const FONT_FALLBACKS: Record<string, Record<string, string>> = {
  // Poppins (geometric sans) → Montserrat or Nunito (also geometric sans with Cyrillic)
  Poppins: { cyrillic: "Montserrat", greek: "Inter" },
  "Baloo 2": { cyrillic: "Nunito", greek: "Open Sans" },
  "Space Grotesk": { cyrillic: "Inter", greek: "Inter" },
  Lato: { cyrillic: "Open Sans", greek: "Open Sans" },
  "Bebas Neue": { cyrillic: "Oswald", greek: "Inter" },
};

declarations.INDIC_LANGUAGE_SCRIPTS:
const INDIC_LANGUAGE_SCRIPTS: Record<string, ScriptSupport> = {
  bn: "bengali",
  gu: "gujarati",
  kn: "kannada",
  ml: "malayalam",
  or: "oriya",
  pa: "gurmukhi",
  ta: "tamil",
  te: "telugu",
};

declarations.scriptForLanguage:
function scriptForLanguage(lang: string): ScriptSupport | null {
  const lower = lang.toLowerCase();
  // Check CJK (needs full locale match for zh-CN vs zh-TW)
  if (CJK_LANGUAGE_MAP[lower]) return CJK_LANGUAGE_MAP[lower];
  const base = lower.split("-")[0];
  if (base === "he") return "hebrew";
  if (base === "th") return "thai";
  if (base === "vi") return "vietnamese";
  if (INDIC_LANGUAGE_SCRIPTS[base]) return INDIC_LANGUAGE_SCRIPTS[base];
  if (CJK_LANGUAGE_MAP[base]) return CJK_LANGUAGE_MAP[base];
  // Arabic
  if (ARABIC_LANGUAGES.has(base)) return "arabic";
  // Cyrillic / Greek / Devanagari
  if (CYRILLIC_LANGUAGES.has(base)) return "cyrillic";
  if (GREEK_LANGUAGES.has(base)) return "greek";
  if (DEVANAGARI_LANGUAGES.has(base)) return "devanagari";
  return null;
}

declarations.languageHasScriptRequirements:
/** Whether a language needs compatibility checks beyond basic Latin glyphs. */
export function languageHasScriptRequirements(language: string): boolean {
  return scriptForLanguage(language) !== null;
}

declarations.resolveFontForLanguage:
/**
 * Returns a compatible font for the given font + target language.
 * If the font already supports the language's script, returns the same font.
 * Otherwise returns the closest visual fallback that does support it.
 *
 * For CJK and Arabic, always returns the dedicated Noto Sans variant
 * because no built-in editor font covers those scripts.
 */
export function resolveFontForLanguage(
  fontFamily: string,
  language: string,
): string {
  const requiredScript = scriptForLanguage(language);
  if (!requiredScript) return fontFamily; // Latin — every font works

  // CJK and Arabic always need a dedicated font
  const scriptFallback = SCRIPT_FALLBACK_FONTS[requiredScript];
  if (scriptFallback) {
    const supported = FONT_SCRIPT_SUPPORT[fontFamily];
    if (supported?.includes(requiredScript)) return fontFamily;
    return scriptFallback;
  }

  const supported = FONT_SCRIPT_SUPPORT[fontFamily];
  if (supported?.includes(requiredScript)) return fontFamily;

  // Need a fallback for Cyrillic/Greek
  const fallback = FONT_FALLBACKS[fontFamily]?.[requiredScript];
  return fallback || (requiredScript === "devanagari" ? "Poppins" : "Inter");
}

declarations.resolveFontForText:
/**
 * Resolve a font from the actual characters being rendered. This is used when
 * stored language metadata is missing or incorrect, which would otherwise let
 * the browser and Lambda choose different platform fallback fonts.
 */
export function resolveFontForText(fontFamily: string, text: string): string {
  if (/\p{Script=Hebrew}/u.test(text))
    return resolveFontForLanguage(fontFamily, "he");
  if (/\p{Script=Thai}/u.test(text))
    return resolveFontForLanguage(fontFamily, "th");
  if (/\p{Script=Bengali}/u.test(text))
    return resolveFontForLanguage(fontFamily, "bn");
  if (/\p{Script=Gujarati}/u.test(text))
    return resolveFontForLanguage(fontFamily, "gu");
  if (/\p{Script=Kannada}/u.test(text))
    return resolveFontForLanguage(fontFamily, "kn");
  if (/\p{Script=Malayalam}/u.test(text))
    return resolveFontForLanguage(fontFamily, "ml");
  if (/\p{Script=Oriya}/u.test(text))
    return resolveFontForLanguage(fontFamily, "or");
  if (/\p{Script=Gurmukhi}/u.test(text))
    return resolveFontForLanguage(fontFamily, "pa");
  if (/\p{Script=Tamil}/u.test(text))
    return resolveFontForLanguage(fontFamily, "ta");
  if (/\p{Script=Telugu}/u.test(text))
    return resolveFontForLanguage(fontFamily, "te");
  if (/\p{Script=Cyrillic}/u.test(text)) {
    return resolveFontForLanguage(fontFamily, "ru");
  }
  if (/\p{Script=Greek}/u.test(text)) {
    return resolveFontForLanguage(fontFamily, "el");
  }
  if (/\p{Script=Arabic}/u.test(text)) {
    return resolveFontForLanguage(fontFamily, "ar");
  }
  if (/\p{Script=Devanagari}/u.test(text)) {
    return resolveFontForLanguage(fontFamily, "hi");
  }
  if (/\p{Script=Hiragana}|\p{Script=Katakana}/u.test(text)) {
    return resolveFontForLanguage(fontFamily, "ja");
  }
  if (/\p{Script=Hangul}/u.test(text)) {
    return resolveFontForLanguage(fontFamily, "ko");
  }
  if (/\p{Script=Han}/u.test(text)) {
    // Han alone cannot distinguish Chinese regions, Japanese or Korean.
    // Retain an already compatible authored CJK family instead of replacing
    // Traditional Chinese or a kanji-only brand with Simplified Chinese.
    if (
      FONT_SCRIPT_SUPPORT[fontFamily]?.some((script) =>
        script.startsWith("cjk-"),
      )
    ) {
      return fontFamily;
    }
    return resolveFontForLanguage(fontFamily, "zh-cn");
  }
  // These letters require the Vietnamese subset rather than Latin/Latin-ext.
  // NFC also handles authored decomposed vowels and combining tone marks.
  if (/[ƠơƯư\u1EA0-\u1EF9]/u.test(text.normalize("NFC"))) {
    return resolveFontForLanguage(fontFamily, "vi");
  }
  return fontFamily;
}

declarations.getRequiredFontForLanguage:
/**
 * Returns the font name that needs to be loaded for a given language,
 * or null if no special font is needed.
 */
export function getRequiredFontForLanguage(language: string): string | null {
  const script = scriptForLanguage(language);
  if (!script) return null;
  return SCRIPT_FALLBACK_FONTS[script] || null;
}

declarations.sizesFor:
function sizesFor(platform: ExportPlatform, device: ExportDevice): string[] {
  if (device === "phone")
    return platform === "ios"
      ? [...Object.keys(iosDisplaySizes), ...Object.keys(iphoneDuoDisplaySizes)]
      : Object.keys(androidDisplaySizes);
  if (device === "tablet" && platform === "ios")
    return Object.keys(ipadDisplaySizes);
  return [];
}

declarations.resolvePreviewSize:
/** Default size: the store's primary size; canvas size where none applies. */
export function resolvePreviewSize(
  platform: ExportPlatform,
  device: ExportDevice,
  displaySize?: PreviewDisplaySize,
): ScreenshotExportSize {
  const allowed = sizesFor(platform, device);
  if (displaySize) {
    if (!allowed.includes(displaySize)) {
      throw new Error(
        allowed.length
          ? `displaySize "${displaySize}" does not apply to ${platform} ${device}. Use one of: ${allowed.join(", ")}.`
          : `${platform} ${device} previews render at the layout's canvas size; omit displaySize.`,
      );
    }
    return { kind: "preset", id: displaySize as never };
  }
  if (device === "phone")
    return { kind: "preset", id: platform === "ios" ? "6.9" : "play-high" };
  if (device === "tablet" && platform === "ios")
    return { kind: "preset", id: "13" };
  return { kind: "canvas" };
}

declarations.previewTarget:
export function previewTarget(input: {
  platform: ExportPlatform;
  device: ExportDevice;
  language: string;
  displaySize?: PreviewDisplaySize;
}): ScreenshotExportTarget {
  return {
    platform: input.platform,
    device: input.device,
    language: input.language,
    size: resolvePreviewSize(input.platform, input.device, input.displaySize),
  };
}

declarations.selectPreviewScreens:
/** Requested screen indexes, validated against the layout. All by default. */
export function selectPreviewScreens(
  layout: Layout,
  requested?: number[],
): number[] {
  const count = layout.screens.length;
  if (count === 0) throw new Error("This layout has no screens to preview");
  if (!requested?.length) return Array.from({ length: count }, (_, i) => i);
  const invalid = requested.filter(
    (index) => !Number.isInteger(index) || index < 0 || index >= count,
  );
  if (invalid.length)
    throw new Error(
      `Screen index ${invalid.join(", ")} is out of range: this layout has screens 0-${count - 1}.`,
    );
  return [...new Set(requested)].sort((a, b) => a - b);
}

declarations.groupPreviewScreens:
/** Group screens into parallel stills; 3D screens get smaller groups. */
export function groupPreviewScreens(
  layout: Layout,
  screens: number[],
): number[][] {
  const has3D = (index: number) =>
    (layout.screens[index]?.screenshots ?? []).some((shot) =>
      Boolean(shot.model3D),
    );
  const groups: number[][] = [];
  let current: number[] = [];
  let currentIs3D = false;
  for (const index of screens) {
    const is3D = has3D(index);
    const limit =
      is3D || currentIs3D
        ? PREVIEW_3D_SCREENS_PER_STILL
        : PREVIEW_SCREENS_PER_STILL;
    if (current.length >= limit || (current.length && is3D !== currentIs3D)) {
      groups.push(current);
      current = [];
    }
    if (current.length === 0) currentIs3D = is3D;
    current.push(index);
  }
  if (current.length) groups.push(current);
  return groups;
}

declarations.previewDimensions:
/** Downscaled size whose longest edge is at most `maxEdge`; never upscales. */
export function previewDimensions(
  width: number,
  height: number,
  maxEdge: number,
): { width: number; height: number } {
  const scale = Math.min(1, maxEdge / Math.max(width, height, 1));
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale)),
  };
}

