export interface SocialLayoutIssue {
  path: Array<string | number>;
  message: string;
}

declarations.socialLayoutIssues:
/**
 * Structural rules every social layout must satisfy before it is stored: one
 * screen, drawn on the format's own canvas. The renderer and editor otherwise
 * crop, letterbox or silently ignore extra screens, so an API caller gets a
 * specific message instead of a design that "saved" but looks wrong.
 */
export function socialLayoutIssues(
  format: SocialFormat,
  layout: unknown,
): SocialLayoutIssue[] {
  const definition = SOCIAL_FORMATS[format];
  if (!definition || !layout || typeof layout !== "object") return [];
  const candidate = layout as {
    screens?: unknown;
    canvasWidth?: unknown;
    canvasHeight?: unknown;
  };
  const issues: SocialLayoutIssue[] = [];
  const screenCount = Array.isArray(candidate.screens)
    ? candidate.screens.length
    : 0;
  if (screenCount !== 1) {
    issues.push({
      path: ["screens"],
      message: `A social layout for ${format} must contain exactly one screen (received ${screenCount}). Put every element on screens[0].`,
    });
  }
  if (candidate.canvasWidth !== definition.width) {
    issues.push({
      path: ["canvasWidth"],
      message: `canvasWidth must be ${definition.width} for ${format} (${definition.width}x${definition.height}); received ${String(candidate.canvasWidth)}.`,
    });
  }
  if (candidate.canvasHeight !== definition.height) {
    issues.push({
      path: ["canvasHeight"],
      message: `canvasHeight must be ${definition.height} for ${format} (${definition.width}x${definition.height}); received ${String(candidate.canvasHeight)}.`,
    });
  }
  return issues;
}

declarations.addSocialLayoutIssues:
/** Report socialLayoutIssues as zod issues under `prefix` (e.g. ["layout"]). */
export function addSocialLayoutIssues(
  ctx: z.RefinementCtx,
  format: SocialFormat,
  layout: unknown,
  prefix: Array<string | number>,
): void {
  for (const issue of socialLayoutIssues(format, layout)) {
    ctx.addIssue({
      code: "custom",
      path: [...prefix, ...issue.path],
      message: issue.message,
    });
  }
}

declarations.applyGraphicsPlatform:
/**
 * Re-skin one social layout for a store platform: device frames and 3D models
 * follow the platform, and a lone store badge swaps to the matching store. A
 * layout that deliberately shows both badges keeps them.
 *
 * Shared by the editor's platform toggle, its export, and the server (MCP
 * platform switch and headless render) so all of them produce the same file.
 */
export function applyGraphicsPlatform(
  layout: Layout,
  platform: GraphicsPlatform,
): Layout {
  const targetBadge = platform === "ios" ? "app_store" : "google_play";
  const badgeCount = layout.screens.reduce(
    (count, screen) =>
      count +
      (screen.illustrations ?? []).filter(
        (ill) => getStoreBadgeVariant(ill) !== null,
      ).length,
    0,
  );
  const shouldSwapBadges = badgeCount < 2;

  const swapBadge = (ill: IllustrationNode): IllustrationNode => {
    const variant = getStoreBadgeVariant(ill);
    if (!variant || variant === targetBadge) return ill;
    const target = getStoreBadgeSwapTarget(variant);
    return { ...ill, path: target.path, signedUrl: target.signedUrl };
  };

  const platformLayout = syncLayoutDevicesToPlatform(layout, platform)!;
  return {
    ...platformLayout,
    screens: platformLayout.screens.map((screen) => ({
      ...screen,
      ...(shouldSwapBadges &&
        screen.illustrations && {
          illustrations: screen.illustrations.map(swapBadge),
        }),
    })),
  };
}

declarations.prepareGraphicsExportLayouts:
/** Match lazy format selection, but only using this language's layouts. */

export function prepareGraphicsExportLayouts(
  layouts: Partial<SocialLayoutMap>,
  formats: SocialFormat[],
  language: string,
  preferredFormat?: SocialFormat | null,
): Partial<SocialLayoutMap> {
  const prepared = { ...layouts };
  const source =
    (preferredFormat ? layouts[preferredFormat] : undefined) ||
    Object.values(layouts).find(Boolean);
  for (const format of formats) {
    if (prepared[format]) continue;
    if (!source) {
      throw new Error(
        `${language} is missing ${SOCIAL_FORMATS[format].label}. Translate that graphics language again before export.`,
      );
    }
    prepared[format] = deriveGraphicsFormat(source, format);
  }
  return prepared;
}

declarations.deriveGraphicsFormat:
/**
 * Build `format` from another format's layout the way the editor's format
 * switch and "Sync to all formats" do: the template's own composition for
 * the target, falling back to proportional rescaling.
 */
export function deriveGraphicsFormat(source: Layout, format: SocialFormat) {
  return normalizeLayerZIndexes(
    deriveLayoutFromTemplate(source, format) ??
      deriveLayoutForFormat(source, SOCIAL_FORMATS[format]),
  );
}

declarations.syncGraphicsFromFormat:
/** Server-side "Sync to all formats": rebuild `targets` from `source`. */
export function syncGraphicsFromFormat(
  source: Layout,
  sourceFormat: SocialFormat,
  targets: readonly SocialFormat[],
): Partial<SocialLayoutMap> {
  const synced: Partial<SocialLayoutMap> = {};
  for (const format of targets) {
    if (format === sourceFormat) continue;
    synced[format] = deriveGraphicsFormat(source, format);
  }
  return synced;
}

declarations.graphicsLayoutMap:
/** Saved layouts of one language as a format map. */
export function graphicsLayoutMap(
  graphics: LoadSocialGraphicsResponse["graphics"],
): Partial<SocialLayoutMap> {
  return Object.fromEntries(
    graphics.map((graphic) => [graphic.format, graphic.layout]),
  ) as Partial<SocialLayoutMap>;
}

declarations.selectGraphicsFormat:
/**
 * One format of a saved variant. A format the variant never saved (older
 * variants predate App Store header/search and the ad sizes) is derived from
 * the primary format exactly as the editor does when the user opens it, and
 * flagged in `derivedFormats` so the caller knows it is not stored yet.
 */
export function selectGraphicsFormat(
  data: LoadSocialGraphicsResponse,
  format: SocialFormat,
): LoadSocialGraphicsResponse & { derivedFormats: SocialFormat[] } {
  const saved = data.graphics.filter((graphic) => graphic.format === format);
  if (saved.length > 0 || data.graphics.length === 0) {
    return { ...data, graphics: saved, derivedFormats: [] };
  }
  const prepared = prepareGraphicsExportLayouts(
    graphicsLayoutMap(data.graphics),
    [format],
    data.language || "default",
    data.socialPrimaryFormat,
  );
  return {
    ...data,
    graphics: [{ format, layout: prepared[format]! }],
    derivedFormats: [format],
  };
}

