   * per-scene atmosphere).
   */
  ambient: z.enum(["none", "subtle", "rich"]).nullable().optional(),
  typography: z.object({
    fontFamily: z.string(),
    titleSize: z.number(),
    subtitleSize: z.number(),
  }),
});

declarations.HookContentSchema:
// =============================================================================
// SCENE CONTENT TYPES
// =============================================================================

const HookContentSchema = z.object({
  appName: z.string().nullable(),
  appNameImageUrl: z.string().nullable().optional(),
  tagline: z.string().nullable(),
  logoUrl: z.string().nullable(),
  showLogo: z.boolean().nullable(),
  appNameStyle: TextStyleSchema.nullable().optional(),
  taglineStyle: TextStyleSchema.nullable().optional(),
  logoPosition: PhonePositionSchema.nullable().optional(),
  logoScale: z.number().min(0.5).max(2).nullable().optional(),
  /** Padding inside the logo card, 0–0.45 (lower = tighter around the icon). */
  logoPadding: z.number().min(0).max(0.45).nullable().optional(),
  textAnimation: TextAnimationSchema,
});

declarations.TextOnlyContentSchema:
const TextOnlyContentSchema = z.object({
  headline: z.string(),
  /** "centered" title card (default) or "statement" (the headline as large as the frame allows). */
  layout: z.enum(TEXT_ONLY_LAYOUTS).nullable().optional(),
  /** A word or short phrase of the headline drawn in the accent colour. */
  emphasis: z.string().nullable().optional(),
  subheadline: z.string().nullable(),
  textAnimation: TextAnimationSchema,
  headlineStyle: TextStyleSchema.nullable().optional(),
  subheadlineStyle: TextStyleSchema.nullable().optional(),
});

declarations.CloseupContentSchema:
const CloseupContentSchema = z.object({
  mediaRotation: MediaRotationSchema.optional(),
  screenshotIndex: z.number().int().min(0),
  video: SceneVideoSchema.nullable().optional(),
  focusRegion: z
    .object({
      x: z.number().min(0).max(100),
      y: z.number().min(0).max(100),
      width: z.number().min(1).max(100),
      height: z.number().min(1).max(100),
    })
    .nullable(),
  caption: z.string().nullable(),
  captionStyle: TextStyleSchema.nullable().optional(),
  frameVariant: z.enum(["flat", "right", "left"]).nullable().optional(),
  phonePosition: PhonePositionSchema.nullable().optional(),
  phoneScale: z.number().min(0.5).max(2.5).nullable().optional(),
  // Where the zoomed focus window sits on screen (center, in % of the frame).
  // Defaults to centered / lower-third when unset. Dragged on the preview.
  focusPosition: PhonePositionSchema.nullable().optional(),
  textAnimation: TextAnimationSchema,
});

declarations.IllustrationOverlaySchema:
// =============================================================================
// ILLUSTRATION OVERLAY
// =============================================================================

const IllustrationOverlaySchema = z.object({
  url: z.string(),
  storagePath: z.string().optional(),
  x: z.number().min(0).max(100).default(50),
  y: z.number().min(0).max(100).default(50),
  scale: z.number().min(0.1).max(4).default(1),
  opacity: z.number().min(0).max(1).default(1),
  rotation: z.number().min(-180).max(180).default(0),
});

declarations.TextOverlaySchema:
// =============================================================================
// FREE-FORM TEXT OVERLAY
// =============================================================================

// Free-form rich text placed anywhere on a scene (added via the "Add Text"
// button). Position/scale/rotation/opacity mirror IllustrationOverlay so it
// plugs into the same drag system; `richContent` holds the Tiptap doc.
const TextOverlaySchema = z.object({
  lineHeight: z.number().min(0.8).max(2).optional(),
  richContent: RichTextContentSchema,
  /** Plain-text mirror of richContent (for labels / accessibility). */
  text: z.string().optional(),
  x: z.number().min(0).max(100).default(50),
  y: z.number().min(0).max(100).default(50),
  scale: z.number().min(0.1).max(4).default(1),
  rotation: z.number().min(-180).max(180).default(0),
  opacity: z.number().min(0).max(1).default(1),
  /** Wrap width as a percentage of the frame width. */
  width: z.number().min(5).max(100).default(60),
  textAlign: z.enum(["left", "center", "right"]).default("center"),
  /** Multiplier applied to the base overlay font size. */
  fontSizeScale: z.number().min(0.2).max(4).default(1),
  textAnimation: TextAnimationSchema,
});

declarations.BaseScenePropsSchema:
// =============================================================================
// BASE SCENE PROPERTIES (shared by all scene types)
// =============================================================================

const BaseScenePropsSchema = z.object({
  /** Editor-only timeline label; never rendered into the video. */
  label: z.string().max(80).optional(),
  duration: z.number().min(1).max(15).nullable(),
  choreography: z.string().nullable(), // choreography preset ID
  kenBurns: KenBurnsConfigSchema.nullable().optional(),
  atmosphere: AtmosphereConfigSchema.nullable().optional(),
  transition: TransitionConfigSchema.nullable().optional(),
  animationSpeed: z.number().min(0.5).max(2).nullable().optional(),
  illustrations: z.array(IllustrationOverlaySchema).optional(),
  textOverlays: z.array(TextOverlaySchema).optional(),
  devices: z.array(SceneDeviceSchema).max(12).optional(),
  hiddenElements: z.array(z.string()).optional(),
  /**
   * Skipped scene: kept in the project and editable, but excluded from
   * playback, export, duration fitting, and audio cues. Lets users park a
   * scene they are unsure about instead of deleting it.
   */
  hidden: z.boolean().optional(),
});

declarations.FeatureSceneSchema:
const FeatureSceneSchema = BaseScenePropsSchema.extend({
  type: z.literal("feature"),
  content: FeatureContentSchema,
});

declarations.TextOnlySceneSchema:
const TextOnlySceneSchema = BaseScenePropsSchema.extend({
  type: z.literal("text-only"),
  content: TextOnlyContentSchema,
});

declarations.CloseupSceneSchema:
const CloseupSceneSchema = BaseScenePropsSchema.extend({
  type: z.literal("closeup"),
  content: CloseupContentSchema,
});

declarations.MultiPhoneSceneSchema:
const MultiPhoneSceneSchema = BaseScenePropsSchema.extend({
  type: z.literal("multi-phone"),
  content: MultiPhoneContentSchema,
});

declarations.CTASceneSchema:
const CTASceneSchema = BaseScenePropsSchema.extend({
  type: z.literal("cta"),
  content: CTAContentSchema,
});

declarations.SceneSchema:
// =============================================================================
// COMBINED SCENE TYPE
// =============================================================================

const SceneSchema = z.discriminatedUnion("type", [
  HookSceneSchema,
  FeatureSceneSchema,
  TextOnlySceneSchema,
  CloseupSceneSchema,
  MultiPhoneSceneSchema,
  CTASceneSchema,
]);

declarations.AudioTrackSchema:
// =============================================================================
// AUDIO (single background music track)
// =============================================================================

const AudioTrackSchema = z.object({
  /** Project-relative storage path, e.g. "promo-media/123-track.mp3". Authoritative. */
  storagePath: z.string(),
  /** Ephemeral signed URL, re-signed on load/export. */
  url: z.string().nullable().optional(),
  /** Original filename, for display in the editor. */
  fileName: z.string().nullable().optional(),
  /** Duration of the uploaded source track, used to bound segment selection. */
  sourceDurationSeconds: z.number().positive().nullable().optional(),
  /** Offset into the source track where promo-video playback begins. */
  startTimeSeconds: z.number().min(0).default(0),
  /** Playback volume, 0–1. */
  volume: z.number().min(0).max(1).default(0.8),
  /** Fade-in length in seconds. */
  fadeInSeconds: z.number().min(0).max(10).default(0),
  /** Fade-out length in seconds. */
  fadeOutSeconds: z.number().min(0).max(10).default(0),
});

declarations.AudioDesignSchema:
const AudioDesignSchema = z.object({
  /** Automatically match one-shot effects to scene and transition motion. */
  effectsEnabled: z.boolean().default(true),
  /** Master gain applied to every derived motion effect. */
  effectsVolume: z.number().min(0).max(1).default(0.4),
  /** Bundled soundtrack chosen for generated videos. Uploaded music overrides it. */
  musicId: z.enum(BACKGROUND_MUSIC_IDS).nullable().optional(),
  /** Master gain for the bundled soundtrack. */
  musicVolume: z.number().min(0).max(1).default(0.24),
  /** Offset into the bundled soundtrack used at the start of the video. */
  musicStartTimeSeconds: z.number().min(0).default(0),
});

declarations.AiGenerationSchema:
// =============================================================================
// AI GENERATION IDENTITY
// =============================================================================

/** Which AI generation (and candidate) produced this video; analytics only. */
const AiGenerationSchema = z.object({
  id: z.string().min(1).max(80),
  candidateId: z.string().max(80).nullable().optional(),
  source: z.enum(PROMO_GENERATION_SOURCES).nullable().optional(),
  round: z.number().int().min(0).max(1000).nullable().optional(),
});

declarations.VideoConfigSchema:
// =============================================================================
// VIDEO CONFIG
// =============================================================================

export const VideoConfigSchema = z.object({
  previewFormat: z
    .enum(
      PREVIEW_FORMAT_OPTIONS.map((option) => option.value) as [
        PreviewFormat,
        ...PreviewFormat[],
      ],
    )
    .optional(),
  version: z.union([z.literal(1), z.literal(2)]).nullable(),
  /** Set once transition names mean content motion (see transitionNaming.ts). */
  transitionNaming: z.literal("content-motion").optional(),
  theme: VideoThemeSchema,
  scenes: z.array(SceneSchema).min(1),
  duration: z.number().nullable(),
  /** Optional single background music track spanning the whole video. */
  audio: AudioTrackSchema.nullable().optional(),
  /** Built-in motion effects for generated videos. */
  audioDesign: AudioDesignSchema.nullable().optional(),
  /** Phone model used for device frames (e.g. "iphone17", "googlepixel"). Defaults to iphone17. */
  phoneId: z.string().nullable().optional(),
  /** Canonical real 3D chassis used by feature scenes. */
  deviceModelId: z.enum(DEVICE_MODEL_IDS).nullable().optional(),
  /** Stable project-relative library paths indexed by every scene/overlay. */
  screenshotPaths: z.array(z.string()).optional(),
  /** Generation that produced this video; carried to edit/export analytics. */
  aiGeneration: AiGenerationSchema.nullable().optional(),
});

declarations.isFeatureScene:
export function isFeatureScene(
  scene: Scene,
): scene is z.infer<typeof FeatureSceneSchema> {
  return scene.type === "feature";
}

declarations.isTextOnlyScene:
export function isTextOnlyScene(
  scene: Scene,
): scene is z.infer<typeof TextOnlySceneSchema> {
  return scene.type === "text-only";
}

declarations.isCloseupScene:
export function isCloseupScene(
  scene: Scene,
): scene is z.infer<typeof CloseupSceneSchema> {
  return scene.type === "closeup";
}

declarations.isMultiPhoneScene:
export function isMultiPhoneScene(
  scene: Scene,
): scene is z.infer<typeof MultiPhoneSceneSchema> {
  return scene.type === "multi-phone";
}

declarations.isPhoneScene:
/** Scenes that render a built-in multi-phone content block. */
export function isPhoneScene<T extends Scene>(
  scene: T,
): scene is T & { type: "multi-phone" } {
  return scene.type === "multi-phone";
}

declarations.isCTAScene:
export function isCTAScene(
  scene: Scene,
): scene is z.infer<typeof CTASceneSchema> {
  return scene.type === "cta";
}

declarations.NormalizedVideoConfig:
export type NormalizedVideoConfig = VideoConfig & {
  theme: VideoTheme;
  scenes: NormalizedScene[];
  duration: number;
};

