declarations.getExportQualityScale:
/** Render scale for an export quality; sizes are authored at 1080p. */
export function getExportQualityScale(quality: "720p" | "1080p") {
  return quality === "720p" ? 0.667 : 1;
}

declarations.scalesToEvenSide:
/** Rounding up (Chrome's capture size) and to nearest (Remotion) agree on an even size. */
function scalesToEvenSide(side: number, scale: number): boolean {
  const exact = side * scale;
  const up = Math.ceil(exact - 1e-9);
  return up % 2 === 0 && Math.round(exact) === up;
}

declarations.getEvenExportQualityScale:
/**
 * The 720p scale for an H.264/H.265 server render, nudged down (well under
 * 1%) until both scaled sides land on even pixel counts however they are
 * rounded. libx264 rejects odd sizes: the App Store preview (886×1920) at
 * 0.667 captures at 591×1281 and every Lambda chunk failed to encode.
 */
export function getEvenExportQualityScale(
  quality: "720p" | "1080p",
  width: number,
  height: number,
): number {
  const base = getExportQualityScale(quality);
  if (base === 1 && width % 2 === 0 && height % 2 === 0) return base;
  for (let step = 0; step <= 500; step += 1) {
    const scale = Math.round((base - step * 0.0001) * 10000) / 10000;
    if (scalesToEvenSide(width, scale) && scalesToEvenSide(height, scale)) {
      return scale;
    }
  }
  return base;
}

declarations.getVideoDimensions:
// Helper to get dimensions based on export settings
export function getVideoDimensions(
  category: ExportCategory,
  size: ExportSize,
): { width: number; height: number; label: string } {
  if (category === "appStore") {
    return APP_STORE_VIDEO_DIMENSIONS[size as AppStoreDisplaySize];
  }
  if (category === "ipad") {
    return IPAD_VIDEO_DIMENSIONS[size as IpadDisplaySize];
  }
  if (category === "creative") {
    return APP_STORE_CREATIVE_VIDEO_DIMENSIONS[size as AppStoreCreativeSize];
  }
  return SOCIAL_VIDEO_DIMENSIONS[size as SocialAspectRatio];
}

