declarations.getTransitionLabel:
/** Short label for a transition type, used in compact UI. */
export function getTransitionLabel(type: string | undefined): string {
  if (!type) return "";
  switch (type) {
    case "cross-fade":
      return "Fade";
    case "slide-left":
      return "Slide L";
    case "slide-right":
      return "Slide R";
    case "wipe-left":
      return "Wipe L";
    case "wipe-right":
      return "Wipe R";
    case "push-up":
      return "Push ↑";
    case "push-down":
      return "Push ↓";
    case "zoom":
      return "Zoom";
    default:
      return type;
  }
}

declarations.migrateTransitionNaming:
export function migrateTransitionNaming<T>(input: T): T {
  if (!input || typeof input !== "object") return input;
  const config = input as {
    transitionNaming?: unknown;
    scenes?: unknown;
  };
  if (config.transitionNaming === TRANSITION_NAMING) return input;
  const scenes = Array.isArray(config.scenes)
    ? config.scenes.map((scene) => {
        const transition = (scene as { transition?: { type?: unknown } })
          ?.transition;
        const mirrored =
          typeof transition?.type === "string"
            ? MIRRORED[transition.type]
            : undefined;
        return mirrored
          ? { ...scene, transition: { ...transition, type: mirrored } }
          : scene;
      })
    : config.scenes;
  return { ...config, scenes, transitionNaming: TRANSITION_NAMING } as T;
}

