export function promoMotionForChoreography(
  choreography: string | null | undefined,
): PromoMotionId {
  switch (choreography) {
    case "slide-left":
      return "glide-left";
    case "slide-right":
      return "glide-right";
    case "rotate-in":
      return "tilt-in";
    case "zoom-through":
      return "drifting-tilt";
    default:
      return "float";
  }
}

