declarations.finishIssue:
function finishIssue(deviceModelId: DeviceModelId, finish: Finish) {
  const allowed = getAcceptedFinishesForDeviceModel(deviceModelId);
  return allowed.includes(finish)
    ? null
    : `Finish "${finish}" is not available for ${DEVICE_MODEL_SPECS[deviceModelId].label} (${deviceModelId}). Use one of: ${allowed.join(", ")}.`;
}

declarations.mockupDeviceSchema:
const mockupDeviceSchema = legacyStateSchema
  .pick({
    selectedMediaPath: true,
    deviceModelId: true,
    motion: true,
    finish: true,
    deviceScale: true,
    showDynamicIsland: true,
    primaryKeyframes: true,
  })
  .extend({
    id: z.string().min(1).max(100),
    name: z.string().max(60),
    start: z.number().min(0).max(59.9),
    end: z.number().min(0.1).max(60).nullable(),
    entrance: z.enum(["none", "fade", "slide", "scale"]),
    exit: z.enum(["none", "fade", "slide", "scale"]),
