declarations.stateSchema:
export const stateSchema = legacyStateSchema
  .extend({
    devices: z
      .array(mockupDeviceSchema)
      .min(1)
      .max(MAX_MOCKUP_DEVICES)
      .optional(),
  })
  .superRefine((state, context) => {
    const legacyFinish = finishIssue(
      state.deviceModelId,
      state.finish as Finish,
    );
    if (legacyFinish && !state.devices?.length)
      context.addIssue({
        code: "custom",
        path: ["finish"],
        message: legacyFinish,
      });
    const ids = new Set<string>();
    state.devices?.forEach((device, index) => {
      if (ids.has(device.id))
        context.addIssue({
          code: "custom",
          path: ["devices", index, "id"],
          message: "Device IDs must be unique",
        });
      ids.add(device.id);
      const end = device.end ?? state.motionDuration;
      if (end > state.motionDuration || end - device.start < 0.099999)
        context.addIssue({
          code: "custom",
          path: ["devices", index, "end"],
          message:
            "Device timing must fit within the composition with at least 0.1s duration",
        });
      const deviceFinish = finishIssue(
        device.deviceModelId,
        device.finish as Finish,
      );
      if (deviceFinish)
        context.addIssue({
          code: "custom",
          path: ["devices", index, "finish"],
          message: deviceFinish,
        });
      if (!device.selectedMediaPath)
        context.addIssue({
          code: "custom",
          path: ["devices", index, "selectedMediaPath"],
          message: "Choose a screenshot or video for each device",
        });
      if (
        new Set(device.primaryKeyframes.map((frame) => frame.id)).size !==
        device.primaryKeyframes.length
      )
        context.addIssue({
          code: "custom",
          path: ["devices", index, "primaryKeyframes"],
          message: "Keyframe IDs must be unique within a device",
        });
    });
  });

declarations.saveSchema:
export const saveSchema = z
  .object({
    generationId: z.string().uuid(),
    /** Omitted: the project's active mockup variant (API/MCP callers). */
    variantId: z.string().uuid().optional(),
    state: stateSchema,
    /**
     * API callers: when a device's model changes kind (phone/duo/tablet/
     * laptop) and its keyframes are still an untouched scene preset, re-fit
     * them to the new model like the create flow does. The editor never sends
     * this, so its saves keep exactly what was authored.
     */
    fitMotionToDevice: z.boolean().optional(),
  })
  .strict()
  .superRefine((value, context) => {
    const audioPath = value.state.audio?.storagePath;
    if (audioPath && !projectMediaPathSchema.safeParse(audioPath).success) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["state", "audio", "storagePath"],
        message: "Audio path must be project-relative",
      });
    }
  });

declarations.MockupAudioTrackSchema:
