export const MockupAudioTrackSchema = z
  .looseObject({
    storagePath: z.string().min(1).nullable().optional(),
    bundledMusicId: z.enum(BACKGROUND_MUSIC_IDS).nullable().optional(),
    url: z.string().nullable().optional(),
