function kf(
  prefix: string,
  index: number,
  time: number,
  pose: Partial<Omit<MockupKeyframe, "id" | "time" | "easing">>,
  easing: MockupKeyframe["easing"] = "ease-in-out",
): MockupKeyframe {
  return {
    id: `${prefix}-${index}`,
    time,
    x: pose.x ?? 0,
    y: pose.y ?? 0,
    rotationX: pose.rotationX ?? 0,
    rotationY: pose.rotationY ?? 0,
    rotationZ: pose.rotationZ ?? 0,
    scale: pose.scale ?? 1,
    easing,
  };
}

