declarations.KEYFRAME_INTERVAL_TOLERANCE_SECONDS:
// Encoders place the last keyframe wherever the stream ends and some round
// the interval up by a frame; only clearly longer GOPs stall parallel seeks.
const KEYFRAME_INTERVAL_TOLERANCE_SECONDS = 0.5;

declarations.VideoProbe:
export interface VideoProbe {
  durationSeconds: number;
  width: number;
  height: number;
  /** mediabunny codec id: avc, hevc, vp8, vp9, av1, … (null when unknown). */
  codec: string | null;
  /** Average packet rate; equals the frame rate for constant-rate video. */
  fps: number | null;
  /** Longest distance between two keyframes (or the stream end), in seconds. */
  maxKeyframeIntervalSeconds: number | null;
  sizeBytes: number | null;
}

declarations.CloudRenderAssessment:
export interface CloudRenderAssessment {
  exportSafe: boolean;
  issues: string[];
}

declarations.assessCloudRenderVideo:
export function assessCloudRenderVideo(
  probe: VideoProbe,
): CloudRenderAssessment {
  const issues: string[] = [];
  if (!probe.codec || !CLOUD_RENDER_CODECS.has(probe.codec)) {
    issues.push(
      `Codec ${probe.codec ?? "unknown"} cannot be decoded by the cloud renderer; use H.264 (avc).`,
    );
  }
  if (Math.min(probe.width, probe.height) > CLOUD_RENDER_MAX_SHORT_SIDE) {
    issues.push(
      `Resolution ${probe.width}x${probe.height} exceeds ${CLOUD_RENDER_MAX_SHORT_SIDE}px on the short side.`,
    );
  }
  if (probe.fps !== null && probe.fps > 60 + FPS_TOLERANCE) {
    issues.push(
      `Frame rate ${probe.fps.toFixed(1)} fps is above 60 fps (${CLOUD_RENDER_FPS} fps recommended).`,
    );
  }
  if (
    probe.maxKeyframeIntervalSeconds !== null &&
    probe.maxKeyframeIntervalSeconds >
      CLOUD_RENDER_KEYFRAME_INTERVAL_SECONDS +
        KEYFRAME_INTERVAL_TOLERANCE_SECONDS
  ) {
    issues.push(
      `Keyframes are ${probe.maxKeyframeIntervalSeconds.toFixed(1)} s apart; the cloud renderer needs one at least every ${CLOUD_RENDER_KEYFRAME_INTERVAL_SECONDS} s.`,
    );
  }
  if (
    probe.sizeBytes !== null &&
    probe.sizeBytes > CLOUD_RENDER_MAX_VIDEO_BYTES
  ) {
    issues.push(
      `File is ${(probe.sizeBytes / (1024 * 1024)).toFixed(1)} MB; screen recordings must be 30 MB or smaller.`,
    );
  }
  return { exportSafe: issues.length === 0, issues };
}

declarations.CLOUD_RENDER_FFMPEG_COMMAND:
/**
 * An ffmpeg command that produces the same profile the editor encodes in the
 * browser: H.264, 30 fps CFR, a keyframe every 2 s, ≤1080 px short side, no
 * audio (the device screen is muted; soundtrack audio is a separate track).
 */
export const CLOUD_RENDER_FFMPEG_COMMAND =
  "ffmpeg -i input.mov -an -c:v libx264 -pix_fmt yuv420p -r 30 -g 60 -keyint_min 60 -sc_threshold 0 " +
  "-vf \"scale='if(lte(iw,ih),min(iw,1080),-2)':'if(lte(iw,ih),-2,min(ih,1080))'\" " +
  "-b:v 3500k -maxrate 3500k -bufsize 7000k -movflags +faststart output.mp4";

declarations.getAcceptedFinishesForDeviceModel:
/**
 * Finishes a saved device may carry: the model's selectable finishes plus its
 * default. The two can differ (iPad/MacBook offer only "silver" but default
 * to the house "black", which they render the same), and create flows store
 * the default, so validation must accept it.
 */
export function getAcceptedFinishesForDeviceModel(
  deviceModelId: DeviceModelId,
): readonly Finish[] {
  const keys = getFinishKeysForDeviceModel(deviceModelId);
  const fallback = getDefaultFinishForDeviceModel(deviceModelId);
  return keys.includes(fallback) ? keys : [...keys, fallback];
}

declarations.BackgroundMusicBeatGrid:
/**
 * Constant-tempo beat grid of a bundled track, for cutting scenes on the beat.
 *
 * Beat n (0-based) is at `beatOffsetSeconds + n * 60 / bpm`; every
 * `beatsPerBar`-th beat from the offset is a downbeat.
 *
 * - `authored`: the track was composed on this grid by
 *   `scripts/promo-music/compose.py`, so it is exact. Their BPMs make one beat a
 *   whole number of frames at 30 fps (90/100/120 BPM = 20/18/15 frames).
 * - `measured`: detected by `scripts/promo-music/beatgrid.py` and cross-checked
 *   against section changes. Beat times are accurate to about 10 ms (validated
 *   on the authored tracks); the downbeat can be half a bar out, which still
 *   lands on a beat.
 */
export interface BackgroundMusicBeatGrid {
  bpm: number;
  beatsPerBar: number;
  /** Time of the first downbeat (beat 1 of a bar). */
  beatOffsetSeconds: number;
  source: "authored" | "measured";
  /** Downbeat where the arrangement opens up: a good place for a hero reveal. */
  liftSeconds?: number;
  /** Downbeat of the closing hit; everything after it is the ring-out. */
  finalHitSeconds?: number;
}

