declarations.validateAssetUploadGrant:
/** No arbitrary destinations, credentials or another project's storage objects. */
export function validateAssetUploadGrant(
  value: unknown,
  request: AssetUploadRequest,
  localOrigin?: string,
): AssetUploadGrant {
  const grant = assetUploadGrantSchema.parse(value, portableParseOptions);
  const metadata = assetUploadMetadata(request);
  const folders = {
    logo: "logo",
    "mockup-media": "mockups",
    illustration: "illustrations",
    background: "backgrounds",
    panorama: "panorama",
    font: "fonts",
    "promo-media": "promo-media",
  };
  const folder = metadata.fileType
    ? folders[metadata.fileType]
    : `${metadata.deviceType}/${metadata.platform}`;
  const url = new URL(grant.uploadUrl);
  const local = localOrigin ? new URL(localOrigin) : undefined;
  const allowedLocal =
    local &&
    ["127.0.0.1", "localhost"].includes(local.hostname) &&
    (url.origin === local.origin ||
      (url.protocol === "http:" &&
        ["127.0.0.1", "localhost"].includes(url.hostname) &&
        url.port === "54321"));
  if (
    grant.projectId !== request.projectId ||
    !grant.path.startsWith(`${folder}/`) ||
    grant.path.slice(folder.length + 1).includes("/") ||
    (!allowedLocal &&
      url.origin !== "https://ubvbpgodmmitzutgshzu.supabase.co") ||
    url.hash ||
    url.username ||
    url.password ||
    decodeURIComponent(url.pathname) !==
      `/storage/v1/object/upload/sign/screenshots/${request.projectId}/${grant.path}` ||
    !url.searchParams.get("token")
  )
    throw new Error("Invalid upload destination");
  return grant;
}

declarations.ScreenCorners3D:
export interface ScreenCorners3D {
  topLeft: { x: number; y: number };
  topRight: { x: number; y: number };
  bottomLeft: { x: number; y: number };
  bottomRight: { x: number; y: number };
}

declarations.resolveFrameScreenCorners:
export function resolveFrameScreenCorners(
  corners: ScreenCorners3D | undefined,
  bezelSize: number,
  frameWidth: number,
  frameHeight: number,
): ScreenCorners3D {
  if (corners) {
    return {
      topLeft: { ...corners.topLeft },
      topRight: { ...corners.topRight },
      bottomLeft: { ...corners.bottomLeft },
      bottomRight: { ...corners.bottomRight },
    };
  }

  return {
    topLeft: { x: bezelSize, y: bezelSize },
    topRight: { x: frameWidth - bezelSize, y: bezelSize },
    bottomLeft: { x: bezelSize, y: frameHeight - bezelSize },
    bottomRight: {
      x: frameWidth - bezelSize,
      y: frameHeight - bezelSize,
    },
  };
}

declarations.createFrameMeshGeometry:
export function createFrameMeshGeometry(
  { topLeft, topRight, bottomLeft, bottomRight }: ScreenCorners3D,
  isFlat: boolean,
): PIXI.MeshGeometry {
  if (isFlat) {
    return new PIXI.MeshGeometry({
      positions: new Float32Array([
        topLeft.x,
        topLeft.y,
        topRight.x,
        topRight.y,
        bottomLeft.x,
        bottomLeft.y,
        bottomRight.x,
        bottomRight.y,
      ]),
      uvs: new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]),
      indices: new Uint32Array([0, 1, 2, 1, 3, 2]),
    });
  }

  const gridColumns = 9;
  const gridRows = 9;
  const positions: number[] = [];
  const uvs: number[] = [];
  const indices: number[] = [];

  for (let row = 0; row < gridRows; row++) {
    for (let column = 0; column < gridColumns; column++) {
      const u = column / (gridColumns - 1);
      const v = row / (gridRows - 1);
      const topX = topLeft.x + (topRight.x - topLeft.x) * u;
      const topY = topLeft.y + (topRight.y - topLeft.y) * u;
      const bottomX = bottomLeft.x + (bottomRight.x - bottomLeft.x) * u;
      const bottomY = bottomLeft.y + (bottomRight.y - bottomLeft.y) * u;

      positions.push(topX + (bottomX - topX) * v, topY + (bottomY - topY) * v);
      uvs.push(u, v);
    }
  }

  for (let row = 0; row < gridRows - 1; row++) {
    for (let column = 0; column < gridColumns - 1; column++) {
      const topLeftIndex = row * gridColumns + column;
      const topRightIndex = topLeftIndex + 1;
      const bottomLeftIndex = (row + 1) * gridColumns + column;
      const bottomRightIndex = bottomLeftIndex + 1;
      indices.push(
        topLeftIndex,
        topRightIndex,
        bottomLeftIndex,
        topRightIndex,
        bottomRightIndex,
        bottomLeftIndex,
      );
    }
  }

  return new PIXI.MeshGeometry({
    positions: new Float32Array(positions),
    uvs: new Float32Array(uvs),
    indices: new Uint32Array(indices),
  });
}

declarations.getFrameScreenSize:
export function getFrameScreenSize({
  topLeft,
  topRight,
  bottomLeft,
  bottomRight,
}: ScreenCorners3D): { width: number; height: number } {
  return {
    width: Math.max(
      Math.abs(topRight.x - topLeft.x),
      Math.abs(bottomRight.x - bottomLeft.x),
    ),
    height: Math.max(
      Math.abs(bottomLeft.y - topLeft.y),
      Math.abs(bottomRight.y - topRight.y),
    ),
  };
}

declarations.getFrameScreenBounds:
export function getFrameScreenBounds({
  topLeft,
  topRight,
  bottomLeft,
  bottomRight,
}: ScreenCorners3D) {
  const xValues = [topLeft.x, topRight.x, bottomLeft.x, bottomRight.x];
  const yValues = [topLeft.y, topRight.y, bottomLeft.y, bottomRight.y];
  const x = Math.min(...xValues);
  const y = Math.min(...yValues);
  return {
    x,
    y,
    width: Math.max(...xValues) - x,
    height: Math.max(...yValues) - y,
  };
}

declarations.CreateFrameScreenMeshOptions:
type CreateFrameScreenMeshOptions = {
  screenshot: PIXI.Texture;
  geometry: PIXI.MeshGeometry;
  cornerRadius: number;
  screenWidth: number;
  screenHeight: number;
  fitMode: ScreenshotFitMode;
  textureOwner?: TextureOwner;
  contentRotation: number;
  contentTransform?: ScreenshotContentTransform;
  cleanStatusBar?: boolean;
  fillPadding?: boolean;
};

declarations.ScreenshotContentMesh:
/** A frame screen mesh that can live-update its content pan/zoom without a full re-render. */
export type ScreenshotContentMesh = PIXI.Mesh & {
  __updateContentTransform?: (
    transform: ScreenshotContentTransform | undefined,
  ) => void;
};

declarations.createFrameScreenMesh:
export function createFrameScreenMesh({
  screenshot,
  geometry,
  cornerRadius,
  screenWidth,
  screenHeight,
  fitMode,
  textureOwner,
  contentRotation,
  contentTransform,
  cleanStatusBar = false,
  fillPadding = true,
}: CreateFrameScreenMeshOptions): PIXI.Mesh {
  // The screen is rasterized onto a canvas before it is mapped into the frame.
  // At the frame image's own screen size that canvas is ~1050px wide for the
  // 1124px flat iPad frame, so an iPad export (device drawn ~1450-1750px wide)
  // squeezed its 2048px screenshot to 1050px and stretched it back up. Raster
  // at the screenshot's own resolution instead, up to 4x the frame's. Editor
  // previews load downscaled screenshots, so they rarely pay for this.
  const rasterScale = Math.min(
    4,
    Math.max(
      1,
      screenshot.width / Math.max(1, screenWidth),
      screenshot.height / Math.max(1, screenHeight),
    ),
  );
  const rasterWidth = screenWidth * rasterScale;
  const rasterHeight = screenHeight * rasterScale;
  const rasterCornerRadius = cornerRadius * rasterScale;
  const texture = applyRoundedCornersToTexture(
    screenshot,
    rasterCornerRadius,
    rasterWidth,
    rasterHeight,
    fitMode,
    textureOwner,
    contentRotation,
    contentTransform,
    cleanStatusBar,
    fillPadding,
  );
  const mesh: ScreenshotContentMesh = new PIXI.Mesh({ geometry, texture });

  // Live preview hook for the on-canvas reposition mode. One canvas and one
  // GPU texture are allocated lazily on the first draft and then redrawn +
  // re-uploaded in place on every subsequent tick, so a drag never allocates
  // per-frame. The texture is registered with the render pass's textureOwner
  // and released with the pass like any other dynamic texture.
  let liveCanvas: HTMLCanvasElement | null = null;
  let liveTexture: PIXI.Texture | null = null;
  mesh.__updateContentTransform = (transform) => {
    if (
      mesh.destroyed ||
      screenshot.destroyed ||
      typeof document === "undefined"
    ) {
      return;
    }
    if (!liveCanvas) {
      liveCanvas = document.createElement("canvas");
      liveCanvas.width = Math.round(rasterWidth);
      liveCanvas.height = Math.round(rasterHeight);
    }
    if (
      !drawRoundedScreenshotContent(
        liveCanvas,
        screenshot,
        rasterCornerRadius,
        fitMode,
        contentRotation,
        transform,
        cleanStatusBar,
        fillPadding,
      )
    ) {
      return;
    }
    if (!liveTexture || liveTexture.destroyed) {
      liveTexture = createDynamicTextureFromSource(liveCanvas, textureOwner, {
        mipmaps: false,
      });
    } else {
      liveTexture.source.update();
    }
    if (mesh.texture !== liveTexture) mesh.texture = liveTexture;
  };
  return mesh;
}

declarations.addFrameSprite:
export function addFrameSprite(
  container: PIXI.Container,
  frameTexture: PIXI.Texture,
  frameWidth: number,
  frameHeight: number,
  isNoFrame: boolean,
): PIXI.Sprite | null {
  if (isNoFrame) return null;

  const frameSprite = new PIXI.Sprite(frameTexture);
  frameSprite.width = frameWidth;
  frameSprite.height = frameHeight;
  container.addChild(frameSprite);
  return frameSprite;
}

declarations.applyFrameTransform:
export function applyFrameTransform(
  container: PIXI.Container,
  frameWidth: number,
  frameHeight: number,
  tiltAngle: number,
): void {
  container.pivot.set(frameWidth / 2, frameHeight / 2);
  if (tiltAngle !== 0) {
    container.rotation = (tiltAngle * Math.PI) / 180;
  }
}

declarations.DeviceModelHinge:
/** A rigid part (the laptop lid) rotating about a hinge axis. */
interface DeviceModelHinge {
  kind: "hinge";
  nodeName: string;
  pivot: [number, number, number];
  closedRotation: [number, number, number];
}

declarations.DeviceModelFold:
/**
 * A book-style foldable driven through its skeleton. The GLB is authored flat
 * open; one half (`movingBone`) swings about the hinge axis onto the other,
 * which stays put, so the closed device shows the cover display on the moving
 * half's back the right way round. The spine follows at half the angle so it
 * covers the fold edge throughout. All coordinates are in the rig's space,
 * which is the skinned meshes' bind space.
 */
export interface DeviceModelFold {
  kind: "fold";
  /** Authored root node, re-oriented to face the camera (Euler XYZ). */
  rootNodeName: string;
  rootRotation: [number, number, number];
  movingBone: string;
  spineBone: string;
  /** Rig-space hinge axis point; the axis itself is rig +Z. */
  pivot: [number, number, number];
  /** Rotation of the moving half at lidOpen 0, about rig +Z. */
  closedAngle: number;
  /**
   * How far the spine slides toward the hinge axis by the time the device is
   * shut. Flat, it sits in a channel under the halves; shut, it has to close
   * up against their edges or the folded display shows through the gap.
   */
  spineLift: number;
  /** Rig-space X extent of one half, for keeping the device centred. */
  halfWidth: number;
  /** Width of the spine when closed (its outermost rig-space |X|). */
  spineDepth: number;
}

declarations.DeviceSecondaryScreen:
/**
 * A second display on the same model (the iPhone Duo's cover screen). It shows
 * the same media as the main display, fitted to its own shape.
 */
interface DeviceSecondaryScreen {
  materialNames: readonly string[];
  aspect: number;
}

declarations.DeviceStillFraming:
/**
 * Offscreen still framing for editor composites, per model.
 *
 * `widthFactor` is the still canvas width as a fraction of the layout canvas
 * width; `aspect` is height/width — above 1 for the portrait handhelds, below 1
 * for the landscape laptop. Transparent margin is trimmed after rendering
 * (`trimTransparentCanvasWithMeta`), so an over-generous box only costs
 * effective resolution, while an under-sized one clips the device.
 */
interface DeviceStillFraming {
  widthFactor: number;
  aspect: number;
}

declarations.DeviceScreenInsets:
/**
 * The display area inside the trimmed still, as fractions of the sprite. Drives
 * the drag/hit bounds and the hover overlay, so it wants to track the glass, not
 * the chassis — a laptop's screen sits in the upper half above its base.
 */
interface DeviceScreenInsets {
  x: number;
  y: number;
  width: number;
  height: number;
  radius: number;
}

declarations.DeviceModelSpec:
interface DeviceModelSpec {
  path: string;
  baseScale: number;
  modelOffset: [number, number, number];
  label: string;
  kind: DeviceModelKind;
  screenMaterialNames: readonly string[];
  /**
   * Display aspect (width/height) of the model's screen surface, used to shape
   * the composited screen texture for non-stretch fit modes. The screen mesh's
   * UVs span 0..1 across the whole display, so a texture of any other shape is
   * distorted onto it - which is exactly what `stretch` is, and what `cover` /
   * `contain` have to counteract.
   *
   * The iPhone and Pixel derive theirs from the geometry constants above, so
   * they cannot drift from the quads actually drawn. The other two are measured
   * from their GLB's screen-mesh POSITION accessor bounds - the meshes come
   * from the asset, so there is nothing in the repo to derive them from:
   *   iPad Pro       0.5522  / 0.73035 ("Screen")
   *   MacBook Pro 14 30.07597 / hypot(6.69185, 18.37419) - the lid is authored
   *                  at 69.99 degrees, so the panel's height is the tilted
   *                  diagonal, not the raw Z extent (1.538 = the real 3024x1964
   *                  panel, which confirms the correction).
   */
  screenAspect: number;
  /**
   * True when the GLB's screen UVs run right-to-left, which renders the
   * screenshot mirrored. Decoded from each model's TEXCOORD_0: U correlates
   * with the mesh's local x at +1.000 on the Pixel and the MacBook, but at
   * -1.000 on the iPad. (The iPhone's screen is our own quad, whose -x UVs are
   * cancelled by the mesh's 180-degree Z rotation.)
   */
  screenMirrorX?: boolean;
  /**
   * Keep the media upright in view when the device is rolled a quarter turn
   * or more (the nearest quarter of its pose's Z rotation), the way a phone's
   * display follows how it is held. Only the Duo needs it: unfolded, its
   * inner display is landscape, and App Store inner shots pose it portrait.
   */
  uprightScreenContent?: boolean;
  secondaryScreen?: DeviceSecondaryScreen;
  supportsCameraHole: boolean;
  still: DeviceStillFraming;
  screenInsets: DeviceScreenInsets;
  hiddenNodeNamePatterns?: readonly RegExp[];
  articulation?: DeviceModelArticulation;
}

