declarations.resolveDeviceModelPath:
export function resolveDeviceModelPath(
  path: string,
  baseUrl = getMcpAssetOrigin()
    ? `${getMcpAssetOrigin()}/`
    : typeof document === "undefined"
      ? undefined
      : document.baseURI,
): string {
  if (!baseUrl) return path;
  try {
    return new URL(path, baseUrl).href;
  } catch {
    return path;
  }
}

