declarations.DEVICE_MODEL_IDS:
/**
 * Every model id, derived from the spec record so it cannot drift. `DeviceModelId`
 * keys the record, so adding a model to the union forces a spec entry and this
 * list follows — use it for zod enums, preloads and option lists rather than
 * restating the ids.
 */
export const DEVICE_MODEL_IDS = Object.keys(DEVICE_MODEL_SPECS) as [
  DeviceModelId,
  ...DeviceModelId[],
];

