declarations.DEVICE_STILL_SCALE:
// Fixed group scale for the offscreen still render, tuned to leave margin for
// the phone to orbit without clipping. (Still canvas dimensions/aspect live in
// ./still/deviceStillRenderer so the PIXI renderer can import them three-free.)
export const DEVICE_STILL_SCALE = 0.62;

declarations.getDefaultLayoutScaleForDeviceModel:
/**
 * Layout scale applied when a device is first added as a 3D model.
 *
 * The still is trimmed to the device's silhouette before it becomes a sprite,
 * so how much canvas a given scale buys depends on how much of its still frame
 * the device fills. A phone is narrow inside a portrait frame and needs scaling
 * up; the laptop nearly fills a landscape frame and needs scaling down.
 */
export function getDefaultLayoutScaleForDeviceModel(
  deviceModelId: DeviceModelId,
): number {
  const kind = DEVICE_MODEL_SPECS[deviceModelId].kind;
  // Added portrait-open (a quarter turned), where it is 1.4x the iPhone's
  // height at one scale.
  if (deviceModelId === "iphone-duo") return 1.15;
  if (kind === "laptop") return 0.8;
  if (kind === "tablet") return 1.2;
  return DEVICE_DEFAULT_LAYOUT_SCALE;
}

declarations.getDefaultPoseForDeviceModel:
/**
 * Default editor pose for a specific chassis.
 *
 * Every kind starts square to the canvas. Laptops especially: even a small
 * inherited roll makes the keyboard and display look accidentally crooked.
 */
export function getDefaultPoseForDeviceModel(deviceModelId?: DeviceModelId) {
  // The iPhone Duo starts unfolded and turned portrait, the way App Store
  // inner-display shots present it; every other chassis starts at Front.
  if (deviceModelId === "iphone-duo") {
    return { ...DEVICE_DEFAULT_POSE, rotationZ: -Math.PI / 2 };
  }
  return { ...DEVICE_DEFAULT_POSE };
}

