declarations.getDesktopFrameDimensions:
/** Natural artwork size, matching the desktop renderer's frame metrics. */
export function getDesktopFrameDimensions(
  desktopId: string,
  variant: "flat" | "none" = "flat",
): { width: number; height: number } | undefined {
  const spec = getDesktopSpec(desktopId);
  if (!spec) return undefined;
  if (variant !== "none") {
    return spec.frameDimensions;
  }
  const { width, height } = cornersToBounds(spec.screenCorners3D);
  return { width, height };
}

